 const details=dayEvents(selected);
 const detailRows=[...details.duties.map(x=>({tone:"event-flight",time:x.time||"Roster",title:x.code||"Flight duty",sub:x.route||"Duty"})),...details.school.map(x=>({tone:"event-holiday",time:"SCHOOL CALENDAR",title:x.title,sub:"SEK · 2026/27"})),...details.lessons.map(x=>({tone:schoolTone(x.subject),time:x.time,title:x.subject,sub:"Sandra · Pre 3A"})),...details.events.map(x=>({tone:"event-family",time:x.type||"Family",title:x.title,sub:"Family event"})),...details.reminders.map(x=>({tone:"event-reminder",time:"REMINDER",title:x.title,sub:reminderLabel(x.repeat)}))];
 const agenda=state.events.map((x,i)=>({...x,kind:"event",index:i})).concat((state.reminders||[]).map((x,i)=>({...x,kind:"reminder",index:i}))).sort((a,b)=>(a.date||a.startDate).localeCompare(b.date||b.startDate));
