function initInteractiveMap(data){const el=$("#flightMap");if(!el)return;if(!window.L){el.classList.add("map-fallback");return}if(flightMapInstance){try{flightMapInstance.remove()}catch(e){}flightMapInstance=null}const L=window.L,map=L.map(el,{zoomControl:false,scrollWheelZoom:false,preferCanvas:true,worldCopyJump:true});flightMapInstance=map;L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{subdomains:"abc",maxZoom:19,attribution:"© OpenStreetMap contributors"}).addTo(map);L.control.zoom({position:"topright"}).addTo(map);const byCode=new Map(data.points.map(p=>[p.code,p]));for(const route of data.paths){const from=byCode.get(route.from),to=byCode.get(route.to);if(!from||!to)continue;L.polyline([[from.lat,from.lon],[to.lat,to.lon]],{color:"#56d7ce",weight:Math.min(5,1.5+route.count*.55),opacity:.72, smoothFactor:1.5}).addTo(map).bindTooltip(route.from+" → "+route.to+" · "+route.count+" sector"+(route.count===1?"":"s"))}const bounds=[];for(const p of data.points){bounds.push([p.lat,p.lon]);L.circleMarker([p.lat,p.lon],{radius:5,weight:2,color:"#06222c",fillColor:"#62e1d2",fillOpacity:.98}).addTo(map).bindPopup("<b>"+esc(p.code)+"</b><br>"+esc(p.country))}if(bounds.length>1)map.fitBounds(bounds,{padding:[34,34],maxZoom:4});else if(bounds.length===1)map.setView(bounds[0],4);else map.setView([24,45],2);requestAnimationFrame(()=>map.invalidateSize())}
function render(){nav();$("#view").innerHTML=views[active]();if(active==="home"){const mapData=flightMapData(state.logbook);if(mapData.sectors>0)initInteractiveMap(mapData)}if(active==="roster"&&pendingPdf){const p=pendingPdf;const box=document.createElement("section");box.className="panel";box.style.marginBottom="16px";box.innerHTML=`<div class="panel-head"><h2>PDF IMPORT REVIEW · ${esc(p.period)}</h2><span class="pill">${p.pageCount} pages</span></div><p class="muted">Crew: ${esc(p.crew)} · Parser: ${esc(p.parser)}</p><div class="grid three"><div><div class="stat-label">DETECTED DUTIES</div><div class="stat">${p.duties.length}</div></div><div><div class="stat-label">BLOCK HOURS</div><div class="stat">${esc(p.stats?.blockHours||"—")}</div></div><div><div class="stat-label">DUTY HOURS</div><div class="stat">${esc(p.stats?.dutyHours||"—")}</div></div></div><div class="list" style="margin:12px 0">${p.duties.map(d=>`<div class="item"><span class="grow"><b>${esc(d.date)} · ${esc(d.code)}</b><small>${esc(d.kind)} · ${esc(d.route)} · RPT ${esc(d.time)}</small></span><span class="pill">${esc(d.source)}</span></div>`).join("")}</div><p class="muted">Hotel stays: ${p.hotels.length} · Training records: ${p.training.length}. El PDF original no se modifica. Comprueba cada día antes de confirmar; la extracción es asistida y puede requerir correcciones.</p><div class="form"><button class="btn primary" id="confirmPdf">Confirm roster import</button><button class="btn ghost" id="cancelPdf">Discard</button></div>`;$("#view").prepend(box);}bind("importBtn",()=>openPicker($("#fileInput")));bind("prevMonth",()=>{let d=new Date((state.calendarMonth||today().slice(0,7))+"-01T12:00:00");d.setMonth(d.getMonth()-1);state.calendarMonth=d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0");render()});bind("nextMonth",()=>{let d=new Date((state.calendarMonth||today().slice(0,7))+"-01T12:00:00");d.setMonth(d.getMonth()+1);state.calendarMonth=d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0");render()});bind("confirmPdf",()=>{if(!pendingPdf)return;let seen=new Set(state.duties.map(x=>x.date+"|"+x.code));let fresh=pendingPdf.duties.filter(x=>!seen.has(x.date+"|"+x.code));state.duties.push(...fresh);state.rosterMeta={period:pendingPdf.period,stats:pendingPdf.stats,hotels:pendingPdf.hotels,training:pendingPdf.training,crew:pendingPdf.crew};pendingPdf=null;save();render();toast(fresh.length+" PDF roster entries imported.");});bind("cancelPdf",()=>{pendingPdf=null;render();toast("PDF import discarded.");});bind("addDuty",()=>{let date=$("#dutyDate").value,code=$("#dutyCode").value.trim();if(!date||!code)return toast("Indica fecha y duty.");state.duties.push({date,code,route:$("#dutyRoute").value,time:$("#dutyTime").value});save();render();toast("Duty guardado localmente.")});bind("generate",async()=>{let d=new Date((state.calendarMonth||today().slice(0,7))+"-01T12:00:00");const {buildMonthlyPlan}=await import("./monthly-planner.js");state.recommendations=state.recommendations.filter(x=>!x.date?.startsWith(state.calendarMonth||today().slice(0,7)));state.recommendations.push(...buildMonthlyPlan(state.duties,d.getFullYear(),d.getMonth()));save();render();toast("Borrador mensual generado para revisión.")});bind("addLog",()=>{let sector={date:$("#logDate").value,from:$("#logFrom").value.trim().toUpperCase(),to:$("#logTo").value.trim().toUpperCase(),hours:$("#logHours").value,flightNumber:$("#logFlight").value.trim(),aircraft:$("#logAircraft").value.trim(),role:$("#logRole").value,landings:$("#logLandings").value,notes:$("#logNotes").value.trim()};let errors=validateSector(sector);if(errors.length)return toast(errors[0]);state.logbook.push(sector);save();render();toast("Sector validated and saved.")});bind("importWader",()=>openPicker($("#waderCsvInput")));bind("exportLogbook",()=>{let blob=new Blob([logbookCsv(state.logbook)],{type:"text/csv;charset=utf-8"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="rumbo-logbook.csv";a.click();URL.revokeObjectURL(a.href);toast("Logbook CSV exported.")});bind("addWorkout",()=>{let workout={date:$("#workDate").value,type:$("#workType").value,minutes:Number($("#workMinutes").value),notes:$("#workNotes").value.trim()};let errors=validateWorkout(workout);if(errors.length)return toast(errors[0]);state.workouts.push(workout);save();render();toast("Training session saved.")});bind("makeTrainingPlan",()=>{let d=new Date((state.calendarMonth||today().slice(0,7))+"-01T12:00:00");state.trainingPlan=suggestTraining(state.duties,d.getFullYear(),d.getMonth(),state.workouts);save();render();toast(state.trainingPlan.length+" candidate sessions prepared for review.")});document.querySelectorAll("[data-accept-plan]").forEach(e=>e.onclick=()=>{let p=state.trainingPlan[Number(e.dataset.acceptPlan)];if(!p)return;state.workouts.push({date:p.date,type:ROUTINES.find(r=>r.id===p.routineId)?.type||"Mobility",minutes:p.minutes,notes:"Accepted draft: "+p.title});state.trainingPlan.splice(Number(e.dataset.acceptPlan),1);save();render();toast("Session added to your training log.")});document.querySelectorAll("[data-skip-plan]").forEach(e=>e.onclick=()=>{state.trainingPlan.splice(Number(e.dataset.skipPlan),1);save();render()});bind("addShop",()=>{let name=$("#shopItem").value.trim();if(!name)return toast("Escribe un producto.");state.shopping.push({name,qty:$("#shopQty").value,done:false});save();render();toast("Añadido a la compra.")});bind("addReminder",()=>{const title=$("#reminderTitle").value.trim(),startDate=$("#reminderDate").value,repeat=$("#reminderRepeat").value;if(!title||!startDate)return toast("Escribe el recordatorio y selecciona una fecha.");state.reminders.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),title,startDate,repeat,createdAt:new Date().toISOString()});save();render();toast("Recordatorio añadido al calendario.")});document.querySelectorAll("[data-reminder-complete]").forEach(e=>e.onclick=()=>{const item=state.reminders.find(r=>r.id===e.dataset.reminderComplete);if(!item)return;item.completedDates=Array.isArray(item.completedDates)?item.completedDates:[];const date=e.dataset.reminderDate;item.completedDates=item.completedDates.includes(date)?item.completedDates.filter(x=>x!==date):[...item.completedDates,date];save();render()});document.querySelectorAll("[data-reminder-remove]").forEach(e=>e.onclick=()=>{if(!confirm("¿Eliminar este recordatorio y sus próximas repeticiones?"))return;state.reminders.splice(Number(e.dataset.reminderRemove),1);save();render();toast("Recordatorio eliminado.")});bind("addEvent",()=>{let date=$("#eventDate").value,title=$("#eventTitle").value.trim();if(!date||!title)return toast("Completa fecha y evento.");state.events.push({date,title});save();render();toast("Evento guardado.")});bind("addExpense",()=>{let date=$("#expenseDate").value,name=$("#expenseName").value.trim(),amount=$("#expenseAmount").value;if(!date||!name||!amount)return toast("Completa los datos del gasto.");state.expenses.push({date,name,amount,currency:$("#expenseCurrency").value});save();render();toast("Gasto guardado.")});bind("askAi",()=>{let q=$("#aiPrompt").value.trim();if(!q)return;const c=buildAssistantContext(state),next=c.nextDuty?dateText(c.nextDuty.date)+" · "+c.nextDuty.code:"none imported";$("#aiAnswer").innerHTML="<b>RUMBO LOCAL CONTEXT</b><p>"+esc("I can currently reference "+c.duties+" roster duties, "+c.events+" family events, "+c.workouts+" workouts, "+c.expenses+" household expenses, "+c.mealSuggestions+" meal suggestions and "+c.shoppingOpen+" open shopping items. Next duty: "+next+".")+" </p><p class='muted'>This is an on-device context summary, not a connected generative AI model. External AI integration and agent actions are not enabled in this build.</p>"});bind("generateMeals",()=>{const start=state.mealWeekStart||today();state.mealWeekStart=start;state.mealPlan=makeMealWeek(start,state.duties);save();render();toast("Seven-day meal draft generated.")});bind("makeMealShopping",async()=>{const {shoppingFromMeals}=await import("./life-intelligence.js");const items=shoppingFromMeals(state.mealPlan||[],RECIPES,state.pantry||[]);const existing=new Set(state.shopping.map(x=>x.name.toLowerCase()));state.shopping.push(...items.filter(x=>!existing.has(x.name.toLowerCase())));save();render();toast("Shopping list generated from the meal plan.")});bind("addPantry",()=>{let name=$("#pantryName").value.trim();if(!name)return toast("Enter a pantry item.");state.pantry=state.pantry||[];state.pantry.push({name,qty:$("#pantryQty").value});save();render();toast("Pantry updated.")});document.querySelectorAll("[data-pantry-remove]").forEach(e=>e.onclick=()=>{state.pantry.splice(Number(e.dataset.pantryRemove),1);save();render()});document.querySelectorAll("[data-recipe]").forEach(e=>e.onclick=()=>{const r=RECIPES.find(x=>x.id===e.dataset.recipe);if(r)alert(r.name+"\\n\\n"+r.ingredients.map(x=>x.join(": ")).join("\\n")+"\\n\\n"+r.steps.map((x,i)=>(i+1)+". "+x).join("\\n"))});bind("dashWeekPrev",()=>{state.dashboardWeekStart=shiftDate(state.dashboardWeekStart||weekStart(today()),-7);save();render()});bind("dashWeekNext",()=>{state.dashboardWeekStart=shiftDate(state.dashboardWeekStart||weekStart(today()),7);save();render()});bind("dashWeekToday",()=>{state.dashboardWeekStart=weekStart(today());save();render()});bind("familyPrev",()=>{state.familyAnchor=modeFamilyShift(state.familyAnchor||today(),state.familyView||"month",-1);save();render()});bind("familyNext",()=>{state.familyAnchor=modeFamilyShift(state.familyAnchor||today(),state.familyView||"month",1);save();render()});bind("familyToday",()=>{state.familyAnchor=today();state.familySelectedDate=today();save();render()});bind("familyMonthView",()=>{state.familyView="month";save();render()});bind("familyWeekView",()=>{state.familyView="week";save();render()});document.querySelectorAll("[data-family-date]").forEach(e=>e.onclick=()=>{state.familySelectedDate=e.dataset.familyDate;save();render()});if($("#familySelectedPicker"))$("#familySelectedPicker").onchange=()=>{state.familySelectedDate=$("#familySelectedPicker").value;state.familyAnchor=state.familySelectedDate;save();render()};bind("addEvent",()=>{let date=$("#eventDate").value,title=$("#eventTitle").value.trim();if(!date||!title)return toast("Complete date and event.");state.events.push({date,title,type:$("#eventType").value});save();render();toast("Family event saved.")});document.querySelectorAll("[data-event-remove]").forEach(e=>e.onclick=()=>{state.events.splice(Number(e.dataset.eventRemove),1);save();render()});bind("addExpense",()=>{let date=$("#expenseDate").value,name=$("#expenseName").value.trim(),amount=Number($("#expenseAmount").value);if(!date||!name||!Number.isFinite(amount)||amount<=0)return toast("Complete valid expense details.");state.expenses.push({date,name,amount,currency:$("#expenseCurrency").value,category:$("#expenseCategory").value});save();render();toast("Household expense saved.")});bind("saveBudget",()=>{let c=$("#budgetCurrency").value,v=Number($("#budgetLimit").value);if(!Number.isFinite(v)||v<=0)return toast("Enter a valid budget.");state.budgets=state.budgets||{};state.budgets[c]=v;save();render();toast("Monthly budget saved.")});document.querySelectorAll("[data-expense-remove]").forEach(e=>e.onclick=()=>{const sorted=state.expenses.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,20),target=sorted[Number(e.dataset.expenseRemove)];state.expenses.splice(state.expenses.indexOf(target),1);save();render()});document.querySelectorAll("[data-shop]").forEach(e=>e.onchange=()=>{state.shopping[Number(e.dataset.shop)].done=e.checked;save();render()})}
$("#fileInput").addEventListener("change",async e=>{
  const f=e.target.files[0]; if(!f)return;
  try{
    let rows=[],summary="";
    if(f.name.toLowerCase().endsWith(".pdf")){
      toast("Leyendo roster PDF…");
      const {parseQatarRosterPDF}=await import("./qatar-pdf-import.js");
      const parsed=await parseQatarRosterPDF(f);
      rows=parsed.duties;
      summary="Periodo: "+parsed.period+"\\nServicios detectados: "+rows.length+"\\nDías con actividad: "+(parsed.summary?.days||0)+"\\nSectores detectados: "+(parsed.summary?.flightSectors||0)+"\\nOFF: "+(parsed.summary?.offDays||0)+" · Standby: "+(parsed.summary?.standbyDays||0)+" · Training: "+(parsed.summary?.trainingDays||0)+"\\nBlock hours: "+(parsed.stats?.blockHours||"No detectadas")+"\\nDuty hours: "+(parsed.stats?.dutyHours||"No detectadas")+"\\nHoteles: "+parsed.hotels.length+" · Formación: "+parsed.training.length;
      if(!rows.length){toast("El PDF se ha abierto, pero no he podido reconocer sus servicios. No se ha importado nada. Prueba con el PDF original de Crew Schedule Report.");console.warn("Qatar PDF preview",parsed);return;}
      const sample=rows.slice(0,18).map(x=>x.date+" · "+x.code+" · "+(x.route||"route pending")+" · RPT "+(x.time||"—")).join("\\n");
      if(!confirm("REVISIÓN DEL ROSTER PDF\\n\\n"+summary+"\\n\\nMuestra de registros:\\n"+sample+"\\n\\n¿Importar estos registros?"))return;
      state.rosterStats=parsed.stats;state.rosterPeriod=parsed.period;state.rosterHotels=parsed.hotels;state.rosterTraining=parsed.training;
    }else{
      const {parseRosterText}=await import("./roster-import.js");
      rows=parseRosterText(await f.text(),f.name);
      if(!rows.length){toast("No se detectaron registros. Revisa el formato.");return;}
    }
    const seen=new Set(state.duties.map(x=>x.date+"|"+x.code));
    const fresh=rows.filter(x=>!seen.has(x.date+"|"+x.code));
    state.duties.push(...fresh);save();active="roster";render();
    toast(fresh.length+" registros importados. Revisa el calendario.");
  }catch(err){console.error(err);toast("No se pudo importar "+f.name+": "+(err.message||"error desconocido"));const box=document.createElement("section");box.className="panel";box.style.marginBottom="14px";box.innerHTML="<b>Importación no completada</b><p class=\"muted\"></p>";box.querySelector("p").textContent=err.message||String(err);$("#view").prepend(box);}
  finally{e.target.value="";}
});
$("#waderCsvInput").addEventListener("change",async e=>{
 const file=e.target.files[0];if(!file)return;
 try{
  const parsed=parseWaderCsv(await file.text()),x=parsed.summary;
  const msg="WADER LOGBOOK IMPORT\\n\\n"+x.flights+" flights\\n"+x.simulatorSessions+" simulator records (separate)\\n"+x.previousExperienceHours.toFixed(2)+" previous-experience hours\\n"+x.recordedFlightHours.toFixed(2)+" dated flight hours\\n"+x.allTimeHours.toFixed(2)+" all-time hours\\n"+x.airports+" airports\\n"+x.dateFrom+" to "+x.dateTo+"\\nAircraft: "+x.aircraft.join(", ")+"\\nPotential duplicate candidates: "+x.duplicateCandidates+"\\n\\nImport these records?";
  if(!confirm(msg))return;
  const seen=new Set(state.logbook.map(v=>[v.date,v.flightNumber||"",v.from,v.to].join("|")));
  const fresh=parsed.flights.filter(v=>{const k=[v.date,v.flightNumber||"",v.from,v.to].join("|");if(seen.has(k))return false;seen.add(k);return true});
  state.logbook.push(...fresh);state.previousExperienceHours=x.previousExperienceHours;
  state.waderImportSummary={...x,importedAt:new Date().toISOString(),simulatorRecords:parsed.simulators,previousExperience:parsed.previous};
  save();active="aviation";render();toast(fresh.length+" Wader sectors imported; "+(parsed.flights.length-fresh.length)+" duplicates skipped.");
 }catch(err){console.error(err);toast("Wader CSV import failed: "+err.message)}
 finally{e.target.value=""}
});
$("#importBackupBtn").onclick=()=>openPicker($("#backupInput"));
$("#backupInput").addEventListener("change",async e=>{
 const file=e.target.files[0];if(!file)return;
 try{
  const parsed=JSON.parse(await file.text()),candidate=parsed?.state;
  if(parsed?.schema!=="rumbo3-local-v1"||!candidate||typeof candidate!=="object"||Array.isArray(candidate))throw new Error("Formato de copia no reconocido.");
  const keys=["duties","events","workouts","shopping","expenses","logbook","recommendations","mealPlan","pantry"];
  for(const key of keys)if(candidate[key]!==undefined&&!Array.isArray(candidate[key]))throw new Error("La sección "+key+" no tiene un formato válido.");
  if(!confirm("Vas a sustituir los datos locales actuales por la copia del "+(parsed.exportedAt||"fecha desconocida")+". Exporta antes una copia actual si quieres conservarlos. ¿Continuar?"))return;
  const safe={...candidate};
  for(const key of keys)if(!Array.isArray(safe[key]))safe[key]=[];
  state=safe;save();render();toast("Copia restaurada en este dispositivo.");
 }catch(err){toast("No se pudo restaurar: "+err.message);}
 finally{e.target.value=""}
});
$("#exportBtn").onclick=()=>{let blob=new Blob([JSON.stringify({schema:"rumbo3-local-v1",exportedAt:new Date().toISOString(),state},null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="rumbo-backup.json";a.click();URL.revokeObjectURL(a.href);toast("Copia local exportada.")};
function showStartupError(message){const host=$("#view");if(host){host.innerHTML="<section class=\"panel\"><div class=\"kicker\">RUMBO RECOVERY</div><h1>RUMBO no ha podido cargar esta pantalla</h1><p>Se ha detectado un error y se ha evitado dejar la aplicación en blanco.</p><pre id=\"rumboStartupError\" style=\"white-space:pre-wrap;color:#f3b6a5\"></pre><button class=\"btn primary\" id=\"rumboReload\">Recargar</button></section>";$("#rumboStartupError").textContent=message;$("#rumboReload").onclick=()=>location.reload()}}
window.addEventListener("error",e=>showStartupError((e.message||"Error JavaScript")+"\nArchivo: "+(e.filename||"no indicado")+"\nLínea: "+(e.lineno||"?")+" · Columna: "+(e.colno||"?")));window.addEventListener("unhandledrejection",e=>showStartupError(e.reason?.stack||e.reason?.message||String(e.reason||"Error al cargar un módulo")));
$("#today").textContent=new Date().toLocaleDateString("es-ES",{weekday:"long",day:"numeric",month:"long",year:"numeric"});try{render()}catch(err){console.error(err);showStartupError(err?.stack||err?.message||String(err))}
loadAirportDirectory().then(()=>{if(active==="home")try{render()}catch(err){console.error("Airport map refresh failed",err)}}).catch(err=>console.warn("Airport directory could not be loaded",err));
if('serviceWorker' in navigator && location.protocol.startsWith('http')) navigator.serviceWorker.register('./sw.js').catch(()=>{});
